86	// assertSaveFailure checks the contract every rejected mid-save save must
87	// honor towards its caller: a non-nil error that names the actual target path
88	// and carries the injected cause.
89	func assertSaveFailure(t *testing.T, err, cause error, path string) {
90		t.Helper()
91		if err == nil {
92			t.Fatal("Save must report the failed save to its caller")
93		}
94		if !errors.Is(err, cause) {
95			t.Errorf("error %v must carry the failure cause %v", err, cause)
96		}
97		msg := err.Error()
98		if !strings.Contains(msg, path) {
99			t.Errorf("error %q must name the target path %q", msg, path)
100		}
101		if !strings.Contains(msg, cause.Error()) {
102			t.Errorf("error %q must state the failure reason %q", msg, cause.Error())
103		}
104	}
105	
106	// assertExistingTargetUntouched verifies that the failed save behaved as if it
107	// never ran for the actual target: identical bytes, the pinned modification
108	// time, the original records in their original order when read back, no
109	// temporary file left anywhere under dir, and the caller's submitted records
110	// unchanged in content and order.
111	func assertExistingTargetUntouched(t *testing.T, dir, path string, original []Batch, originalBytes []byte, reg *Registry, submitted []Batch) {
112		t.Helper()
113		info, err := os.Stat(path)
